args.query:
\dt api.*
\dv api.*
\d api.application
\d api.app_user
\d api.audit
\d api.company
select policyname,tablename,cmd,roles,qual,with_check from pg_policies;
select tgname,tgrelid::regclass,pg_get_triggerdef(oid) from pg_trigger where not tgisinternal;
select relname,relrowsecurity,relforcerowsecurity,relkind from pg_class where relnamespace='api'::regnamespace;
select grantee,table_name,privilege_type,column_name from information_schema.column_privileges where table_schema='api' and grantee in ('applicant','expert','fund_admin','anon','authenticator','PUBLIC') order by 2,1,4;

alter table api.application add column internal_score numeric;
grant select(internal_score), update(internal_score) on api.application to expert;
grant select(internal_score), insert(internal_score), update(internal_score), references(internal_score) on api.application to fund_admin;
select grantee,privilege_type from information_schema.column_privileges where table_schema='api' and table_name='application' and column_name='internal_score';
select has_column_privilege('applicant','api.application','internal_score','select'), has_column_privilege('applicant','api.application','internal_score','update'), has_column_privilege('applicant','api.application','internal_score','insert'), has_column_privilege('anon','api.application','internal_score','select');
notify pgrst,'reload schema';
